// FFprobe 9.0.2 packet records for the native terminal matrix, read with
// `-fflags +noparse+nofillin -show_packets -show_data -of json` from the literal
// file (`file`) and from a nonseekable pipe (`pipe`). Field values are FFprobe's
// own spelling; `data` holds the bytes of its hexdump. `file` is present for the
// cases the matrix also reads from a seekable source, and says when the file
// record equals the pipe record.
pub struct Packet {
    pub codec_type: &'static str,
    pub stream_index: usize,
    pub pts: Option<i64>,
    pub pts_time: Option<&'static str>,
    pub dts: Option<i64>,
    pub dts_time: Option<&'static str>,
    pub duration: Option<i64>,
    pub duration_time: Option<&'static str>,
    pub size: &'static str,
    pub pos: Option<&'static str>,
    pub flags: &'static str,
    pub data: &'static [u8],
}
pub struct Probe {
    pub rc: i32,
    pub packets: &'static [Packet],
}
pub enum File {
    SameAsPipe,
    Own(Probe),
}
pub struct Case {
    pub name: &'static str,
    pub raw: &'static [u8],
    pub pipe: Probe,
    pub file: Option<File>,
}
